', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_minimal/shopping-home-page--framework-vanilla-js--style-dark/google/gemini-3-flash-preview__s2/styles.css', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents=':root {
    --bg-color: #0a0a0a;
    --surface-color: #1a1a1a;
    --surface-hover: #252525;
    --text-primary: #ffffff;
    --text-secondary: #a0a0a0;
    --accent-color: #3b82f6;
    --accent-hover: #60a5fa;
    --border-color: #333333;
    --container-width: 1200px;
    --transition: all 0.3s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Inter', sans-serif;
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

.btn:focus-visible, 
.icon-btn:focus-visible, 
.add-to-cart:focus-visible,
input:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

/* Header */
.site-header {
    padding: 1.5rem 0;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    background-color: rgba(10, 10, 10, 0.8);
    backdrop-filter: blur(10px);
    z-index: 100;
}

.site-header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
    text-decoration: none;
    color: var(--text-primary);
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    text-decoration: none;
    color: var(--text-secondary);
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--text-primary);
}

.header-actions {
    display: flex;
    gap: 1.5rem;
}

.icon-btn {
    background: none;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    padding: 0.5rem;
    border-radius: 50%;
    transition: var(--transition);
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
}

.icon-btn:hover {
    background-color: var(--surface-hover);
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background-color: var(--accent-color);
    color: white;
    font-size: 0.7rem;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero */
.hero {
    display: flex;
    align-items: center;
    min-height: 80vh;
    padding: 4rem 0;
    gap: 4rem;
    max-width: var(--container-width);
    margin: 0 auto;
}

.hero-content {
    flex: 1;
    padding: 0 2rem;
}

.hero-content h1 {
    font-size: 4rem;
    line-height: 1.1;
    margin-bottom: 1.5rem;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: 2.5rem;
}

.hero-actions {
    display: flex;
    gap: 1rem;
}

.hero-image {
    flex: 1.2;
    height: 600px;
}

.hero-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 8px;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 1rem 2rem;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
    cursor: pointer;
    border: none;
}

.btn-primary {
    background-color: var(--text-primary);
    color: var(--bg-color);
}

.btn-primary:hover {
    background-color: #e0e0e0;
}

.btn-secondary {
    background-color: transparent;
    color: var(--text-primary);
    border: 1px solid var(--border-color);
}

.btn-secondary:hover {
    background-color: var(--surface-hover);
}

/* Product Section */
.products-section {
    padding: 6rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.5rem;
}

.view-all {
    color: var(--text-secondary);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: var(--transition);
}

.view-all:hover {
    color: var(--text-primary);
    border-bottom-color: var(--text-primary);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
}

.product-card:hover {
    transform: translateY(-5px);
}

.product-image {
    position: relative;
    aspect-ratio: 4/5;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.add-to-cart {
    position: absolute;
    bottom: 1rem;
    right: 1rem;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background-color: var(--text-primary);
    color: var(--bg-color);
    border: none;
    cursor: pointer;
    font-size: 1.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transform: translateY(10px);
    transition: var(--transition);
}

.product-card:hover .add-to-cart {
    opacity: 1;
    transform: translateY(0);
}

.product-info {
    padding: 1.5rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.product-info .price {
    color: var(--text-secondary);
}

/* Deals Section */
.deals-section {
    padding: 4rem 0;
}

.deals-banner {
    background-color: var(--surface-color);
    display: flex;
    border-radius: 12px;
    overflow: hidden;
    align-items: center;
}

.deals-text {
    flex: 1;
    padding: 4rem;
}

.badge {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background-color: var(--accent-color);
    color: white;
    font-size: 0.8rem;
    font-weight: 600;
    border-radius: 20px;
    margin-bottom: 1rem;
}

.deals-text h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.deals-text p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.deals-image {
    flex: 1;
    height: 500px;
}

.deals-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Editorial Section */
.editorial-section {
    padding: 6rem 0;
}

.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 2rem;
}

.editorial-card {
    position: relative;
    border-radius: 8px;
    overflow: hidden;
    background-color: var(--surface-color);
}

.editorial-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    opacity: 0.7;
}

.editorial-content {
    position: absolute;
    bottom: 0;
    left: 0;
    padding: 3rem;
    width: 100%;
    background: linear-gradient(transparent, rgba(0,0,0,0.8));
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.editorial-content p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    max-width: 400px;
}

.read-more {
    color: var(--text-primary);
    text-decoration: none;
    font-weight: 600;
    border-bottom: 1px solid var(--text-primary);
}

/* Footer */
.site-footer {
    padding: 6rem 0 3rem;
    border-top: 1px solid var(--border-color);
    margin-top: 6rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: 1.5fr 1fr 1fr 1.5fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    display: block;
    margin-bottom: 1.5rem;
}

.footer-brand p {
    color: var(--text-secondary);
}

.footer-links h4, .footer-newsletter h4 {
    margin-bottom: 1.5rem;
    font-size: 1.1rem;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 0.75rem;
}

.footer-links a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--text-primary);
}

.footer-newsletter p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    padding: 0.75rem 1rem;
    border-radius: 4px;
    color: var(--text-primary);
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.social-links {
    display: flex;
    gap: 1.5rem;
}

.social-links a {
    color: var(--text-secondary);
    text-decoration: none;
}

/* Responsive */
@media (max-width: 992px) {
    .hero {
        flex-direction: column;
        text-align: center;
        padding: 2rem 0;
    }
    .hero-image {
        width: 100%;
        height: 400px;
    }
    .hero-actions {
        justify-content: center;
    }
    .deals-banner {
        flex-direction: column;
    }
    .editorial-grid {
        grid-template-columns: 1fr;
    }
    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none; /* Mobile menu logic would go here */
    }
    .hero-content h1 {
        font-size: 2.5rem;
    }
    .footer-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
}

.mobile-menu-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    position: relative;
    width: 30px;
    height: 30px;
}

.hamburger, .hamburger::before, .hamburger::after {
    display: block;
    width: 24px;
    height: 2px;
    background-color: var(--text-primary);
    position: absolute;
    transition: var(--transition);
}

.hamburger {
    top: 50%;
    transform: translateY(-50%);
}

.hamburger::before {
    content: '';
    top: -8px;
}

.hamburger::after {
    content: '';
    top: 8px;
}

.mobile-menu-toggle[aria-expanded="true"] .hamburger {
    background-color: transparent;
}

.mobile-menu-toggle[aria-expanded="true"] .hamburger::before {
    transform: translateY(8px) rotate(45deg);
}

.mobile-menu-toggle[aria-expanded="true"] .hamburger::after {
    transform: translateY(-8px) rotate(-45deg);
}

@media (max-width: 768px) {
    .mobile-menu-toggle {
        display: block;
    }

    .nav-links.active {
        display: flex;
        flex-direction: column;
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        background-color: var(--bg-color);
        padding: 2rem;
        border-bottom: 1px solid var(--border-color);
    }
}
